<?php
declare(strict_types=1);
require_once __DIR__ . '/../includes/functions.php';$pdo=db();$challenges=$pdo->query("SELECT cc.*,COALESCE((SELECT SUM(quantity) FROM challenge_contributions x WHERE x.challenge_id=cc.id),0) progress,(SELECT COUNT(*) FROM challenge_participations cp WHERE cp.challenge_id=cc.id) participants FROM community_challenges cc WHERE cc.status='active' ORDER BY cc.end_date ASC")->fetchAll();$pageTitle='Community challenges';require __DIR__ . '/../includes/header.php'; ?>
<section class="page-hero"><div class="shell"><span class="eyebrow" style="color:#FFD928">Make it a movement</span><h1>Community challenges.</h1><p>Every number comes from items charities have confirmed as received. Demo challenges are clearly labelled.</p></div></section><section class="section"><div class="shell"><?php if(!$challenges):?><div class="empty"><span class="empty-icon">✦</span>No active community challenges right now.</div><?php else:?><div class="request-grid"><?php foreach($challenges as $challenge):$percent=min(100,round($challenge['progress']/$challenge['target_items']*100));?><article class="challenge-card"><span class="chip chip-sun"><?=$challenge['is_demo']?'demo challenge':'active challenge'?></span><h2 style="margin:14px 0 8px"><?=e($challenge['title'])?></h2><p style="color:#cac8c0;font-size:13px;line-height:1.6"><?=e($challenge['description'])?></p><div class="progress"><span style="width:<?=$percent?>%"></span></div><div class="progress-info" style="color:#e5e3dc"><span><?=$challenge['progress']?> / <?=$challenge['target_items']?> items</span><span><?=$challenge['participants']?> donors</span></div><p style="font-size:12px;color:#c8c6be">Ends <?=format_date($challenge['end_date'])?><?= $challenge['category']?' · '.e($challenge['category']):''?></p><a class="button button-small button-sun" href="<?=e(url('donor/matcher.php'))?>">Match my clothes →</a></article><?php endforeach;?></div><?php endif;?></div></section>
<?php require __DIR__ . '/../includes/footer.php'; ?>
